package sonar.calculator.mod.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/** Exact Techne boxes, UV offsets and pivots from Calculator 1.12 (MIT). Generated by convert_assets_models.py. */
public final class ModelTransmitter {
    private ModelTransmitter() {}
    public static LayerDefinition createLayer() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        root.addOrReplaceChild("Centre", CubeListBuilder.create().texOffs(0, 36).addBox(0.0F, 0.0F, 0.0F, 2.0F, 26.0F, 2.0F), PartPose.offsetAndRotation(-1.0F, -8.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Bar1", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 20.0F, 1.0F, 1.0F), PartPose.offsetAndRotation(-10.0F, -4.0F, 1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Bar2", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 20.0F, 1.0F, 1.0F), PartPose.offsetAndRotation(-10.0F, -4.0F, -2.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Bar3", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 20.0F, 1.0F, 1.0F), PartPose.offsetAndRotation(1.0F, -4.0F, 10.0F, 0.0F, 1.570796F, 0.0F));
        root.addOrReplaceChild("Bar4", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 20.0F, 1.0F, 1.0F), PartPose.offsetAndRotation(-2.0F, -4.0F, 10.0F, 0.0F, 1.570796F, 0.0F));
        root.addOrReplaceChild("Middle", CubeListBuilder.create().texOffs(0, 11).addBox(0.0F, 0.0F, 0.0F, 4.0F, 9.0F, 4.0F), PartPose.offsetAndRotation(-2.0F, 1.0F, -2.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Bottom", CubeListBuilder.create().texOffs(0, 24).addBox(0.0F, 0.0F, 0.0F, 6.0F, 6.0F, 6.0F), PartPose.offsetAndRotation(-3.0F, 18.0F, -3.0F, 0.0F, 0.0F, 0.0F));
        return LayerDefinition.create(mesh, 128, 64);
    }
    public static void render(ModelPart root, PoseStack poses, VertexConsumer vertices, int light, int overlay) {
        root.getChild("Centre").render(poses, vertices, light, overlay);
        root.getChild("Bar1").render(poses, vertices, light, overlay);
        root.getChild("Bar2").render(poses, vertices, light, overlay);
        root.getChild("Bar3").render(poses, vertices, light, overlay);
        root.getChild("Bar4").render(poses, vertices, light, overlay);
        root.getChild("Middle").render(poses, vertices, light, overlay);
        root.getChild("Bottom").render(poses, vertices, light, overlay);
    }
}
